# ============================================================
# SCRIPT 33
# Assemble final thesis results package
#
# IMPORTANT:
# - This script performs NO new statistical analysis.
# - It does NOT duplicate or copy final figures/tables.
# - It verifies the canonical outputs generated by Scripts 31, 32 and 34.
# - It creates a package index and concise narrative summary.
# ============================================================

source("03_scripts/00_project_config.R")

cat(
  "\n========================================\n",
  "SCRIPT 33\n",
  "ASSEMBLE FINAL THESIS RESULTS PACKAGE\n",
  "========================================\n"
)

# ============================================================
# 1. Canonical locations
# ============================================================

final_result_dir_s33 <-
  "04_results/final_summary"

final_table_dir_s33 <-
  "06_tables/final"

figure_root_s33 <-
  "05_figures/manuscript"

main_figure_dir_s33 <-
  file.path(
    figure_root_s33,
    "main"
  )

individual_figure_dir_s33 <-
  file.path(
    figure_root_s33,
    "individual"
  )

supplementary_figure_dir_s33 <-
  file.path(
    figure_root_s33,
    "supplementary"
  )

for (
  dir_s33 in c(
    final_result_dir_s33,
    final_table_dir_s33,
    figure_root_s33,
    main_figure_dir_s33,
    individual_figure_dir_s33,
    supplementary_figure_dir_s33
  )
) {
  
  if (
    !dir.exists(
      dir_s33
    )
  ) {
    
    stop(
      paste(
        "Missing required canonical directory:",
        dir_s33
      )
    )
  }
}

# ============================================================
# 2. Required Script 31 final tables
# ============================================================

required_tables_s33 <-
  c(
    "Table_01_cohort_and_PCD_discovery_summary.csv",
    "Table_02_subtype_validation_summary.csv",
    "Table_03_MPCDS_validation_summary.csv",
    "Table_04_timeROC_and_DCA_summary.csv",
    "Table_05_therapy_and_immunotherapy_summary.csv",
    "Table_06_sensitivity_analyses_summary.csv",
    "Table_07_PCA_Sankey_integrative_summary.csv",
    "Table_final_headline_results.csv",
    "Table_manifest.csv"
  )

required_table_paths_s33 <-
  file.path(
    final_table_dir_s33,
    required_tables_s33
  )

table_check_s33 <-
  data.frame(
    file =
      required_table_paths_s33,
    exists =
      file.exists(
        required_table_paths_s33
      ),
    size_bytes =
      file.info(
        required_table_paths_s33
      )$size,
    stringsAsFactors =
      FALSE
  )

cat(
  "\n========================================\n",
  "FINAL TABLE CHECK\n",
  "========================================\n"
)

print(
  table_check_s33,
  row.names = FALSE
)

stopifnot(
  all(
    table_check_s33$exists
  ),
  all(
    table_check_s33$size_bytes > 0
  )
)

# ============================================================
# 3. Required Scripts 32 and 34 publication manifest
# ============================================================

figure_manifest_file_s33 <-
  file.path(
    figure_root_s33,
    "Publication_figure_manifest.csv"
  )

if (
  !file.exists(
    figure_manifest_file_s33
  )
) {
  
  stop(
    paste(
      "Missing publication manifest (run Scripts 32 and 34 first):",
      figure_manifest_file_s33
    )
  )
}

figure_manifest_s33 <-
  read.csv(
    figure_manifest_file_s33,
    stringsAsFactors = FALSE,
    check.names = FALSE
  )

required_manifest_columns_s33 <-
  c(
    "file",
    "category",
    "exists",
    "size_bytes"
  )

stopifnot(
  all(
    required_manifest_columns_s33 %in%
      colnames(
        figure_manifest_s33
      )
  )
)

# Re-check current filesystem instead of trusting stored flags.
figure_manifest_s33$current_exists <-
  file.exists(
    figure_manifest_s33$file
  )

figure_manifest_s33$current_size_bytes <-
  file.info(
    figure_manifest_s33$file
  )$size

cat(
  "\n========================================\n",
  "FINAL FIGURE CHECK\n",
  "========================================\n"
)

figure_category_summary_s33 <-
  aggregate(
    current_exists ~ category,
    data =
      figure_manifest_s33,
    FUN =
      length
  )

colnames(
  figure_category_summary_s33
)[
  colnames(
    figure_category_summary_s33
  ) ==
    "current_exists"
] <-
  "files"

print(
  figure_category_summary_s33,
  row.names = FALSE
)

stopifnot(
  all(
    figure_manifest_s33$current_exists
  ),
  all(
    figure_manifest_s33$current_size_bytes > 0
  )
)

# 7 main + 32 individual (including five pathways and four GEO ROC panels) +
# 7 supplementary figures,
# each in PNG + PDF + TIFF.
expected_main_files_s33 <- 7L * 3L
expected_individual_files_s33 <- 32L * 3L
expected_supplementary_files_s33 <- 7L * 3L
expected_total_figure_files_s33 <-
  expected_main_files_s33 +
  expected_individual_files_s33 +
  expected_supplementary_files_s33

# Require each of the five Script 34 figures in all three formats.
pathway_stems_s33 <- paste0(
  "Figure_PCD_", sprintf("%02d", 1:5), "_",
  c("Apoptosis", "Necroptosis", "Pyroptosis", "Ferroptosis", "Cuproptosis")
)
pathway_files_s33 <- as.vector(outer(
  file.path(individual_figure_dir_s33, "pcd_pathways", pathway_stems_s33),
  c(".png", ".pdf", ".tiff"), paste0
))
missing_pathway_files_s33 <- setdiff(pathway_files_s33, figure_manifest_s33$file)
if (length(missing_pathway_files_s33)) {
  stop("Missing Script 34 pathway figures in publication manifest: ",
       paste(missing_pathway_files_s33, collapse = ", "))
}

# Require the combined ROC figure and all four standalone GEO panels.
roc_stems_s33 <- c(
  file.path(supplementary_figure_dir_s33,
            "Figure_S11_LUAD_MPCDS_time_dependent_ROC"),
  file.path(individual_figure_dir_s33, "external_validation",
            paste0("Figure_EV_", c("GSE68465", "GSE72094",
                                   "GSE31210", "GSE50081"),
                   "_MPCDS_timeROC"))
)
roc_files_s33 <- as.vector(outer(roc_stems_s33,
                                 c(".png", ".pdf", ".tiff"), paste0))
missing_roc_files_s33 <- setdiff(roc_files_s33, figure_manifest_s33$file)
if (length(missing_roc_files_s33)) {
  stop("Missing Script 32 ROC figures in publication manifest: ",
       paste(missing_roc_files_s33, collapse = ", "))
}

observed_main_files_s33 <-
  sum(
    figure_manifest_s33$category ==
      "Main"
  )

observed_individual_files_s33 <-
  sum(
    figure_manifest_s33$category ==
      "Individual"
  )

observed_supplementary_files_s33 <-
  sum(
    figure_manifest_s33$category ==
      "Supplementary"
  )

observed_total_figure_files_s33 <-
  nrow(
    figure_manifest_s33
  )

# ============================================================
# 4. Required Script 31 headline-results file
# ============================================================

headline_file_s33 <-
  file.path(
    final_result_dir_s33,
    "Thesis_headline_results.csv"
  )

stopifnot(
  file.exists(
    headline_file_s33
  )
)

headline_results_s33 <-
  read.csv(
    headline_file_s33,
    stringsAsFactors = FALSE,
    check.names = FALSE
  )

required_headline_columns_s33 <-
  c(
    "topic",
    "headline",
    "interpretation_boundary"
  )

stopifnot(
  all(
    required_headline_columns_s33 %in%
      colnames(
        headline_results_s33
      )
  )
)

# ============================================================
# 5. Build concise thesis-results narrative
# ============================================================

narrative_lines_s33 <-
  c(
    "FINAL THESIS RESULTS PACKAGE",
    "",
    paste0(
      "Generated from the validated analytical pipeline through Scripts 32 and 34. ",
      "No new statistical modelling is performed in Script 33."
    ),
    "",
    "HEADLINE RESULTS",
    ""
  )

for (
  i_s33 in seq_len(
    nrow(
      headline_results_s33
    )
  )
) {
  
  narrative_lines_s33 <-
    c(
      narrative_lines_s33,
      paste0(
        i_s33,
        ". ",
        headline_results_s33$topic[
          i_s33
        ]
      ),
      paste0(
        "Result: ",
        headline_results_s33$headline[
          i_s33
        ]
      ),
      paste0(
        "Interpretation boundary: ",
        headline_results_s33$interpretation_boundary[
          i_s33
        ]
      ),
      ""
    )
}

narrative_lines_s33 <-
  c(
    narrative_lines_s33,
    "CANONICAL OUTPUT STRUCTURE",
    "",
    "Figures:",
    "  05_figures/manuscript/main/",
    "  05_figures/manuscript/individual/",
    "  05_figures/manuscript/individual/pcd_pathways/ (five literature-based schematics)",
    "  05_figures/manuscript/individual/external_validation/ (four GEO ROC panels)",
    "  05_figures/manuscript/supplementary/",
    "",
    "Tables:",
    "  06_tables/final/",
    "",
    "Final summaries:",
    "  04_results/final_summary/",
    "",
    paste0(
      "Publication figure files verified: ",
      observed_total_figure_files_s33,
      " (",
      observed_main_files_s33,
      " main, ",
      observed_individual_files_s33,
      " individual, ",
      observed_supplementary_files_s33,
      " supplementary)."
    ),
    "",
    paste0(
      "Final thesis table files verified: ",
      nrow(
        table_check_s33
      ),
      "."
    ),
    "",
    paste0(
      "Important: the package is an index of canonical outputs. ",
      "Files are not duplicated into a second final folder."
    )
  )

narrative_file_s33 <-
  file.path(
    final_result_dir_s33,
    "Final_thesis_results_narrative.txt"
  )

writeLines(
  narrative_lines_s33,
  narrative_file_s33
)

# ============================================================
# 6. Build unified final-package index
# ============================================================

table_index_s33 <-
  data.frame(
    category =
      "Table",
    subcategory =
      "Final thesis table",
    file =
      required_table_paths_s33,
    exists =
      file.exists(
        required_table_paths_s33
      ),
    size_bytes =
      file.info(
        required_table_paths_s33
      )$size,
    stringsAsFactors =
      FALSE
  )

figure_index_s33 <-
  data.frame(
    category =
      "Figure",
    subcategory =
      figure_manifest_s33$category,
    file =
      figure_manifest_s33$file,
    exists =
      figure_manifest_s33$current_exists,
    size_bytes =
      figure_manifest_s33$current_size_bytes,
    stringsAsFactors =
      FALSE
  )

summary_files_s33 <-
  c(
    headline_file_s33,
    narrative_file_s33
  )

summary_index_s33 <-
  data.frame(
    category =
      "Summary",
    subcategory =
      c(
        "Headline results",
        "Narrative summary"
      ),
    file =
      summary_files_s33,
    exists =
      file.exists(
        summary_files_s33
      ),
    size_bytes =
      file.info(
        summary_files_s33
      )$size,
    stringsAsFactors =
      FALSE
  )

final_package_index_s33 <-
  rbind(
    table_index_s33,
    figure_index_s33,
    summary_index_s33
  )

package_index_file_s33 <-
  file.path(
    final_result_dir_s33,
    "Final_thesis_results_package_index.csv"
  )

write.csv(
  final_package_index_s33,
  package_index_file_s33,
  row.names = FALSE
)

# ============================================================
# 7. Script inventory
# ============================================================

script_files_s33 <-
  list.files(
    "03_scripts",
    pattern = "^[0-9]{2}_.*\\.[Rr]$",
    full.names = TRUE,
    recursive = FALSE
  )

script_number_s33 <-
  suppressWarnings(
    as.integer(
      sub(
        "^([0-9]{2}).*$",
        "\\1",
        basename(
          script_files_s33
        )
      )
    )
  )

script_inventory_s33 <-
  data.frame(
    script_number =
      script_number_s33,
    file =
      script_files_s33,
    exists =
      file.exists(
        script_files_s33
      ),
    size_bytes =
      file.info(
        script_files_s33
      )$size,
    stringsAsFactors =
      FALSE
  )

script_inventory_s33 <-
  script_inventory_s33[
    order(
      script_inventory_s33$script_number,
      script_inventory_s33$file
    ),
    ,
    drop = FALSE
  ]

script_inventory_file_s33 <-
  file.path(
    final_result_dir_s33,
    "Final_script_inventory.csv"
  )

write.csv(
  script_inventory_s33,
  script_inventory_file_s33,
  row.names = FALSE
)

# ============================================================
# 8. Final package audit
# ============================================================

package_audit_s33 <-
  data.frame(
    metric =
      c(
        "Final thesis table files",
        "Canonical main figure files",
        "Canonical individual figure files",
        "Canonical supplementary figure files",
        "Canonical total figure files",
        "Headline-result sections",
        "Workflow steps",
        "Workflow external GEO subtype cohorts",
        "Workflow LUAD MPCDS external cohorts"
      ),
    observed =
      c(
        nrow(
          table_check_s33
        ),
        observed_main_files_s33,
        observed_individual_files_s33,
        observed_supplementary_files_s33,
        observed_total_figure_files_s33,
        nrow(
          headline_results_s33
        ),
        6,
        8,
        4
      ),
    expected =
      c(
        9,
        expected_main_files_s33,
        expected_individual_files_s33,
        expected_supplementary_files_s33,
        expected_total_figure_files_s33,
        17,
        6,
        8,
        4
      ),
    stringsAsFactors =
      FALSE
  )

package_audit_s33$matches_expected <-
  package_audit_s33$observed ==
  package_audit_s33$expected

cat(
  "\n========================================\n",
  "FINAL SCRIPT 33 PACKAGE AUDIT\n",
  "========================================\n"
)

print(
  package_audit_s33,
  row.names = FALSE
)

stopifnot(
  all(
    package_audit_s33$matches_expected
  )
)

# ============================================================
# 9. Final output-file verification
# ============================================================

final_outputs_s33 <-
  c(
    narrative_file_s33,
    package_index_file_s33,
    script_inventory_file_s33
  )

final_output_check_s33 <-
  data.frame(
    file =
      final_outputs_s33,
    exists =
      file.exists(
        final_outputs_s33
      ),
    size_bytes =
      file.info(
        final_outputs_s33
      )$size,
    stringsAsFactors =
      FALSE
  )

cat(
  "\n========================================\n",
  "FINAL SCRIPT 33 OUTPUT CHECK\n",
  "========================================\n"
)

print(
  final_output_check_s33,
  row.names = FALSE
)

stopifnot(
  all(
    final_output_check_s33$exists
  ),
  all(
    final_output_check_s33$size_bytes > 0
  )
)

cat(
  "\nEstablished final-package regression checks: PASSED\n"
)

cat(
  "\n========================================\n",
  "SCRIPT 33 FINAL THESIS RESULTS PACKAGE COMPLETED SUCCESSFULLY\n",
  "========================================\n"
)